import React, { useEffect, useState } from 'react';

function ProductsList() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [showModal, setShowModal] = useState(false);
  const [editingProduct, setEditingProduct] = useState(null);

  const token = localStorage.getItem('token');

  // =========================
  // FETCH PRODUCTS
  // =========================
  const fetchProducts = async () => {
    try {
      const res = await fetch('http://localhost:8000/api/productes', { // Ajusta el puerto si es necesario
        headers: {
          Accept: 'application/json',
          Authorization: token ? `Bearer ${token}` : undefined
        }
      });

      if (!res.ok) throw new Error('Error al obtenir els productes');

      const data = await res.json();
      setProducts(Array.isArray(data.dades) ? data.dades : []);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  // =========================
  // DELETE PRODUCT
  // =========================
  const handleDelete = async (id) => {
    if (!token) {
      alert('No estás autenticado. Inicia sesión primero.');
      return;
    }

    if (!window.confirm('Segur que vols eliminar aquest producte?')) return;

    try {
      const res = await fetch(`http://localhost:8000/api/productes/${id}`, {
        method: 'DELETE',
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: 'application/json'
        },
      });

      if (res.status === 401) {
        throw new Error('No autorizado. El token ha caducado o es inválido.');
      }

      const data = await res.json();

      if (!res.ok || data.exit === false) {
        throw new Error(data.missatge || 'Error eliminant producte');
      }

      setProducts(products.filter(p => p.id !== id));
      alert(data.missatge);
    } catch (err) {
      alert(err.message);
    }
  };

  // =========================
  // OPEN MODAL
  // =========================
  const openEditModal = (product) => {
    setEditingProduct({ ...product });
    setShowModal(true);
  };

  // =========================
  // HANDLE INPUT CHANGE
  // =========================
  const handleChange = (e) => {
    setEditingProduct({
      ...editingProduct,
      [e.target.name]: e.target.value
    });
  };

  // =========================
  // SAVE PRODUCT
  // =========================
  const handleSave = async () => {
    if (!token) {
      alert('No estás autenticado. Inicia sesión primero.');
      return;
    }

    try {
      const res = await fetch(
        `http://localhost:8000/api/productes/${editingProduct.id}`,
        {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
            Accept: 'application/json'
          },
          body: JSON.stringify(editingProduct)
        }
      );

      if (res.status === 401) {
        throw new Error('No autorizado. El token ha caducado o es inválido.');
      }

      const data = await res.json();

      if (!res.ok || data.exit === false) {
        throw new Error(data.missatge || 'Error actualitzant producte');
      }

      setProducts(products.map(p =>
        p.id === editingProduct.id ? editingProduct : p
      ));

      setShowModal(false);

    } catch (err) {
      alert(err.message);
    }
  };

  // =========================
  // RENDER
  // =========================
  if (loading) return <p>Carregant productes...</p>;
  if (error) return <p>Error: {error}</p>;
  if (products.length === 0) return <p>No hi ha productes disponibles.</p>;

  return (
    <div>
      <h2 className="mb-3">Productes</h2>

      <table className="table table-striped">
        <thead>
          <tr>
            <th>Nom</th>
            <th>Referència</th>
            <th>Descripció</th>
            <th>Quantitat</th>
            <th>Accions</th>
          </tr>
        </thead>
        <tbody>
          {products.map(product => (
            <tr key={product.id}>
              <td>{product.nom}</td>
              <td>{product.referencia}</td>
              <td>{product.descripcio}</td>
              <td>{product.quantitat}</td>
              <td>
                <button
                  className="btn btn-sm btn-primary me-2"
                  onClick={() => openEditModal(product)}
                >
                  Editar
                </button>
                <button
                  className="btn btn-sm btn-danger"
                  onClick={() => handleDelete(product.id)}
                >
                  Eliminar
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* ========================= MODAL ========================= */}
      {showModal && (
        <div className="modal show d-block" tabIndex="-1">
          <div className="modal-dialog">
            <div className="modal-content">

              <div className="modal-header">
                <h5 className="modal-title">Editar producte</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setShowModal(false)}
                />
              </div>

              <div className="modal-body">
                <input
                  className="form-control mb-2"
                  name="nom"
                  value={editingProduct.nom}
                  onChange={handleChange}
                  placeholder="Nom"
                />
                <input
                  className="form-control mb-2"
                  name="referencia"
                  value={editingProduct.referencia}
                  onChange={handleChange}
                  placeholder="Referència"
                />
                <textarea
                  className="form-control mb-2"
                  name="descripcio"
                  value={editingProduct.descripcio}
                  onChange={handleChange}
                  placeholder="Descripció"
                />
                <input
                  type="number"
                  className="form-control"
                  name="quantitat"
                  value={editingProduct.quantitat}
                  onChange={handleChange}
                  placeholder="Quantitat"
                />
              </div>

              <div className="modal-footer">
                <button
                  className="btn btn-secondary"
                  onClick={() => setShowModal(false)}
                >
                  Cancel·lar
                </button>
                <button
                  className="btn btn-success"
                  onClick={handleSave}
                >
                  Guardar
                </button>
              </div>

            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default ProductsList;
